(function(){
  var G=Arena.Game;G._running=false;
  window.__ajuste=function(clase){
    var W=G.world;
    G.setPlayerClass(clase);
    var p=W.getPlayer();
    p.pos.x=0;p.pos.z=0;p.yaw=0;
    for(var i=0;i<16;i++){W.stepSeconds(1/30);G.renderer.syncVisuals(1/30);}
    G.renderer.render(1,1/30);
    var v=G.renderer.visuals[p.id];
    v.root.updateMatrixWorld(true);
    /* Caja del CUERPO desnudo: sólo el SkinnedMesh, sin equipo. */
    var cuerpo=null;
    v.root.traverse(function(o){ if(o.isSkinnedMesh&&!cuerpo) cuerpo=o; });
    function caja(obj){
      var mn=[1e9,1e9,1e9], mx=[-1e9,-1e9,-1e9];
      obj.updateMatrixWorld(true);
      var g=obj.geometry; if(!g) return null;
      var pos=g.attributes.position; var m=obj.matrixWorld.elements;
      for(var i=0;i<pos.count;i++){
        var x=pos.getX(i),y=pos.getY(i),z=pos.getZ(i);
        var wx=m[0]*x+m[4]*y+m[8]*z+m[12];
        var wy=m[1]*x+m[5]*y+m[9]*z+m[13];
        var wz=m[2]*x+m[6]*y+m[10]*z+m[14];
        if(wx<mn[0])mn[0]=wx; if(wx>mx[0])mx[0]=wx;
        if(wy<mn[1])mn[1]=wy; if(wy>mx[1])mx[1]=wy;
        if(wz<mn[2])mn[2]=wz; if(wz>mx[2])mx[2]=wz;
      }
      return {mn:mn,mx:mx};
    }
    var cb=caja(cuerpo);
    var piezas=[];
    (v.gear||[]).forEach(function(o){
      o.traverse(function(c){
        if(!c.isMesh||c.isSkinnedMesh) return;
        var b=caja(c); if(!b) return;
        piezas.push({n:(c.name||o.name||'?').replace('gear:',''),
          y:[+b.mn[1].toFixed(3),+b.mx[1].toFixed(3)],
          ancho:+(b.mx[0]-b.mn[0]).toFixed(3),
          fondo:+(b.mx[2]-b.mn[2]).toFixed(3),
          alto:+(b.mx[1]-b.mn[1]).toFixed(3)});
      });
    });
    return {clase:clase,
      cuerpo:{y:[+cb.mn[1].toFixed(3),+cb.mx[1].toFixed(3)],
              ancho:+(cb.mx[0]-cb.mn[0]).toFixed(3), fondo:+(cb.mx[2]-cb.mn[2]).toFixed(3)},
      piezas:piezas};
  };return 'listo';})()
